  function readColors(id){return qa('#'+id+' input[type=color]').map(x=>x.value)}
  function railData(){return qa('#siteRailRows .site-rail-row').map(r=>({icon:r.querySelector('[data-rail="icon"]').value.trim(),label:r.querySelector('[data-rail="label"]').value.trim(),subtitle:r.querySelector('[data-rail="subtitle"]').value.trim(),href:r.querySelector('[data-rail="href"]').value.trim(),visible:r.querySelector('[data-rail="visible"]').checked})).filter(x=>x.label)}
  function renderRail(items){const box=q('#siteRailRows');if(!box)return;const arr=Array.isArray(items)?items:defaults.collection_rail;box.innerHTML=arr.map((x,i)=>`<div class="site-rail-row"><input data-rail="icon" value="${esc(x.icon||'')}"><input data-rail="label" value="${esc(x.label||'')}"><input data-rail="subtitle" value="${esc(x.subtitle||'')}"><input data-rail="href" value="${esc(x.href||'')}"><label class="site-check"><input data-rail="visible" type="checkbox" ${x.visible!==false?'checked':''}> Shfaqe</label><div class="site-rail-actions"><button type="button" data-up>↑</button><button type="button" data-down>↓</button></div></div>`).join('');qa('#siteRailRows .site-rail-row').forEach((r,i)=>{r.querySelector('[data-up]').onclick=()=>moveRail(i,-1);r.querySelector('[data-down]').onclick=()=>moveRail(i,1)})}
  function moveRail(i,d){const a=railData(),j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];renderRail(a)}
  function layoutData(){return qa('#siteLayoutRows .site-layout-row').map(r=>({key:r.dataset.key,label:r.dataset.label,visible:r.querySelector('[data-layout-visible]').checked}))}
  function renderLayout(items){const box=q('#siteLayoutRows');if(!box)return;const src=Array.isArray(items)&&items.length?items:defaults.layout;const known=new Map(defaults.layout.map(x=>[x.key,x]));const arr=[];src.forEach(x=>{if(known.has(x.key)&&!arr.some(y=>y.key===x.key))arr.push({...known.get(x.key),...x})});defaults.layout.forEach(x=>{if(!arr.some(y=>y.key===x.key))arr.push({...x})});box.innerHTML=arr.map((x,i)=>`<div class="site-layout-row ${x.visible===false?'is-hidden':''}" data-key="${esc(x.key)}" data-label="${esc(x.label)}"><span class="site-drag">⋮⋮</span><div><span class="site-layout-name">${esc(x.label)}</span><span class="site-layout-key">${esc(x.key)}</span></div><label class="site-check"><input data-layout-visible type="checkbox" ${x.visible!==false?'checked':''}> Shfaqe</label><div class="site-layout-actions"><button type="button" data-layout-up>↑</button><button type="button" data-layout-down>↓</button></div></div>`).join('');
    qa('#siteLayoutRows .site-layout-row').forEach((r,i)=>{r.querySelector('[data-layout-up]').onclick=()=>moveLayout(i,-1);r.querySelector('[data-layout-down]').onclick=()=>moveLayout(i,1);r.querySelector('[data-layout-visible]').onchange=()=>r.classList.toggle('is-hidden',!r.querySelector('[data-layout-visible]').checked)})
  }
  function moveLayout(i,d){const a=layoutData(),j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];renderLayout(a)}
  function bannerData(){return qa('#siteBannerRows .site-banner-row').map((r,i)=>({id:r.dataset.id||('banner_'+Date.now()+'_'+i),title:r.querySelector('[data-banner="title"]').value.trim(),subtitle:r.querySelector('[data-banner="subtitle"]').value.trim(),button_label:r.querySelector('[data-banner="button_label"]').value.trim(),href:r.querySelector('[data-banner="href"]').value.trim(),product_id:r.querySelector('[data-banner="product_id"]')?.value||'',image_url:r.querySelector('[data-banner="image_url"]').value.trim(),position:r.querySelector('[data-banner="position"]').value,device:r.querySelector('[data-banner="device"]').value,banner_type:r.querySelector('[data-banner="banner_type"]')?.value||'promo',theme:r.querySelector('[data-banner="theme"]')?.value||'dark',start_at:r.querySelector('[data-banner="start_at"]')?.value||'',end_at:r.querySelector('[data-banner="end_at"]')?.value||'',visible:r.querySelector('[data-banner="visible"]').checked})).filter(x=>x.title||x.image_url)}
  function renderBanners(items){const box=q('#siteBannerRows');if(!box)return;const arr=Array.isArray(items)?items:[];box.innerHTML=arr.map((x,i)=>bannerRow(x,i)).join('');bindBannerRows()}
  function productOptions(selected=''){return '<option value="">— Link manual —</option>'+productRows.map(b=>'<option value="'+esc(b.id)+'" '+(String(selected)===String(b.id)?'selected':'')+'>'+esc(b.title||b.sku||'Libër')+'</option>').join('')}
  function bannerRow(x={},i=0){
    const id=esc(x.id||('banner_'+Date.now()+'_'+i));
    const active=x.visible!==false;
    const type=x.banner_type||'promo';
    const theme=x.theme||'dark';
    const title=esc(x.title||'Baner i ri'),subtitle=esc(x.subtitle||''),button=esc(x.button_label||'Shiko më shumë');
    const img=x.image_url?'<img src="'+esc(x.image_url)+'" alt="">':'';
    const preview='<div class="site-banner-preview-copy"><strong>'+title+'</strong><span>'+subtitle+'</span><b>'+button+' →</b></div>'+img;
    return `<div class="site-banner-row ${active?'':'is-inactive'}" data-id="${id}">
      <div class="site-banner-head">
        <div class="site-banner-title-wrap"><span class="site-banner-number">${i+1}</span><div><strong>${title}</strong><div style="margin-top:3px;font-size:9px;color:#8b98a4">${esc(bannerPositions.find(p=>p[0]===(x.position||'before_newsletter'))?.[1]||'Pozicion i zgjedhur')}</div></div></div>
        <div class="site-banner-toolbar"><span class="site-banner-status ${active?'':'off'}">${active?'● Aktiv':'○ Joaktiv'}</span><label class="site-check"><input data-banner="visible" type="checkbox" ${active?'checked':''}> Shfaqe</label><div class="site-banner-actions"><button type="button" title="Lart" data-banner-up>↑</button><button type="button" title="Poshtë" data-banner-down>↓</button><button type="button" title="Dubliko" data-banner-duplicate>⧉</button><button type="button" class="danger" title="Fshi" data-banner-delete>×</button></div></div>
      </div>
      <div class="site-banner-grid">
        <div class="site-banner-section-label">Përmbajtja</div>
        <div class="site-field span-2"><label>Titulli kryesor</label><input data-banner="title" value="${title}" placeholder="p.sh. Oferta e javës"></div>
        <div class="site-field"><label>Lloji</label><select data-banner="banner_type"><option value="promo" ${type==='promo'?'selected':''}>Ofertë / Promo</option><option value="product" ${type==='product'?'selected':''}>Libër / Produkt</option><option value="announcement" ${type==='announcement'?'selected':''}>Njoftim</option></select></div>
        <div class="site-field"><label>Stili</label><select data-banner="theme"><option value="dark" ${theme==='dark'?'selected':''}>Premium i errët</option><option value="light" ${theme==='light'?'selected':''}>I çelët</option><option value="sale" ${theme==='sale'?'selected':''}>Ofertë / Sale</option></select></div>
        <div class="site-field span-2"><label>Nëntitulli</label><textarea data-banner="subtitle" rows="2" placeholder="Përshkrim i shkurtër i ofertës">${subtitle}</textarea></div>
        <div class="site-field"><label>Teksti i butonit</label><input data-banner="button_label" value="${button}" placeholder="Porosit tani"></div>
        <div class="site-field"><label>Lidhe direkt me një libër</label><select data-banner="product_id">${productOptions(x.product_id||'')}</select><small class="muted-small">Zgjedhja e librit e çon klientin direkt te faqja e porosisë.</small></div>

        <div class="site-banner-section-label">Linku & vendosja</div>
        <div class="site-field span-2"><label>Linku manual</label><input data-banner="href" value="${esc(x.href||'')}" placeholder="product.html?id=... ose https://..."><small class="muted-small">Përdore për kategori, ofertë ose faqe tjetër. Nëse është zgjedhur libër, ai ka përparësi.</small></div>
        <div class="site-field"><label>Pozita në ballinë</label><select data-banner="position">${bannerPositions.map(([v,l])=>`<option value="${v}" ${x.position===v?'selected':''}>${l}</option>`).join('')}</select></div>
        <div class="site-field"><label>Pajisja</label><select data-banner="device"><option value="all" ${x.device!=='desktop'&&x.device!=='mobile'?'selected':''}>Desktop + telefon</option><option value="desktop" ${x.device==='desktop'?'selected':''}>Vetëm desktop</option><option value="mobile" ${x.device==='mobile'?'selected':''}>Vetëm telefon</option></select></div>

        <div class="site-banner-section-label">Foto & planifikimi</div>
        <div class="site-field span-2"><label>Foto e banerit</label><input id="bannerImage_${id}" data-banner="image_url" value="${esc(x.image_url||'')}" placeholder="URL e fotos"><button type="button" class="secondary-btn" data-media-target="bannerImage_${id}" data-media-preview="bannerPreview_${id}" style="margin-top:6px">▧ Zgjidh nga Media Manager</button></div>
        <div class="site-banner-schedule"><div class="site-field"><label>Shfaq nga</label><input data-banner="start_at" type="datetime-local" value="${esc(x.start_at||'')}"><small class="muted-small">Lëre bosh për menjëherë.</small></div><div class="site-field"><label>Shfaq deri</label><input data-banner="end_at" type="datetime-local" value="${esc(x.end_at||'')}"><small class="muted-small">Lëre bosh pa afat.</small></div></div>
        <div class="site-banner-preview" id="bannerPreview_${id}" data-theme="${esc(theme)}">${preview}</div>
      </div>
    </div>`;
  }
  function bindBannerRows(){qa('#siteBannerRows .site-banner-row').forEach((row,i)=>{
    row.querySelector('[data-banner-up]').onclick=()=>moveBanner(i,-1);
    row.querySelector('[data-banner-down]').onclick=()=>moveBanner(i,1);
    row.querySelector('[data-banner-delete]').onclick=()=>{const arr=bannerData();arr.splice(i,1);renderBanners(arr)};
    row.querySelector('[data-banner-duplicate]').onclick=()=>{const arr=bannerData(),copy={...arr[i],id:'banner_'+Date.now(),title:(arr[i]?.title||'Baner')+' – kopje'};arr.splice(i+1,0,copy);renderBanners(arr)};
    const img=row.querySelector('[data-banner="image_url"]'),prev=row.querySelector('.site-banner-preview'),title=row.querySelector('[data-banner="title"]'),sub=row.querySelector('[data-banner="subtitle"]'),btn=row.querySelector('[data-banner="button_label"]'),theme=row.querySelector('[data-banner="theme"]');
    const refreshPreview=()=>{if(!prev)return;prev.dataset.theme=theme?.value||'dark';prev.innerHTML='<div class="site-banner-preview-copy"><strong>'+esc(title?.value||'Baner')+'</strong><span>'+esc(sub?.value||'')+'</span><b>'+esc(btn?.value||'Shiko më shumë')+' →</b></div>'+(img?.value.trim()?'<img src="'+esc(img.value.trim())+'" alt="">':'')};
    [img,title,sub,btn,theme].forEach(el=>el?.addEventListener(el?.tagName==='SELECT'?'change':'input',refreshPreview));
    const product=row.querySelector('[data-banner="product_id"]'),href=row.querySelector('[data-banner="href"]');
    product?.addEventListener('change',()=>{if(product.value&&href){href.value='product.html?id='+encodeURIComponent(product.value);const b=productRows.find(x=>String(x.id)===String(product.value));if(b&&title&&!title.value.trim())title.value=b.title||'';refreshPreview()}});
    const vis=row.querySelector('[data-banner="visible"]');vis?.addEventListener('change',()=>{row.classList.toggle('is-inactive',!vis.checked);const badge=row.querySelector('.site-banner-status');if(badge){badge.classList.toggle('off',!vis.checked);badge.textContent=vis.checked?'● Aktiv':'○ Joaktiv'}})
  })}
  function moveBanner(i,d){const a=bannerData(),j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];renderBanners(a)}
  function collect(){return{menu_colors:readColors('siteDesignMenu'),category_colors:readColors('siteDesignCategories'),feature_colors:readColors('siteDesignFeatures'),why_colors:readColors('siteDesignWhy'),rail_colors:readColors('siteDesignRail'),hover_strength:q('#siteDesignHover')?.value||'vivid',hero_background:q('#siteDesignHeroMode')?.value||'library',hero_tint:q('#siteDesignHeroTint')?.value||'#f3cfc5',hero_shelf_opacity:Number(q('#siteDesignShelf')?.value||22),collection_rail:railData(),layout:layoutData(),banners:bannerData()}}
